package dev.inscribedqa;
import java.util.*;import dev.inscribed.altar.*;import dev.inscribed.recipe.*;import dev.inscribed.ritual.*;import dev.inscribed.config.*;import dev.inscribed.knowledge.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.neoforged.neoforge.gametest.*;import net.neoforged.fml.ModList;
@GameTestHolder("inscribed_rc") @PrefixGameTestTemplate(false)
public final class ReleaseAuthoringTests {
 static final BlockPos T=new BlockPos(10,2,10),S=T.offset(0,0,-3);
 static ResourceLocation id(String s){return ResourceLocation.parse(s);}
 @GameTest(template="test_altar",batch="rc_toggles") public static void optionalLsbcToggleChoosesNoopAndRestores(GameTestHelper h){boolean old=InscribedConfig.LSBC_KNOWLEDGE.get();try{InscribedConfig.LSBC_KNOWLEDGE.set(false);h.assertTrue(KnowledgeIntegrations.get() instanceof NoKnowledgeIntegration,"LSBC toggle failed");InscribedConfig.LSBC_KNOWLEDGE.set(true);h.assertTrue((KnowledgeIntegrations.get() instanceof NoKnowledgeIntegration)==!ModList.get().isLoaded("lsbc"),"LSBC toggle did not restore installed bridge");h.succeed();}finally{InscribedConfig.LSBC_KNOWLEDGE.set(old);}}
 @GameTest(template="test_altar",timeoutTicks=300) public static void authoredAdvancedExtractionPreservesOtherEnchantments(GameTestHelper h){extract(h,"example:fortune_advanced",Items.IRON_PICKAXE);}
 @GameTest(template="test_altar",timeoutTicks=300) public static void authoredCreateExtractionWorksOnlyWithProvider(GameTestHelper h){if(!ModList.get().isLoaded("create")){h.assertTrue(InscribedRecipeRegistry.recipes().stream().noneMatch(r->r.id().equals(id("example:create_capacity"))),"Absent provider recipe loaded");h.succeed();return;}extract(h,"example:create_capacity",BuiltInRegistries.ITEM.get(id("create:copper_backtank")));}
 static void extract(GameTestHelper h,String name,Item item){var r=InscribedRecipeRegistry.recipes().stream().filter(v->v.id().equals(id(name))).findFirst().orElseThrow();h.setBlock(T,Blocks.ENCHANTING_TABLE);h.setBlock(S,Blocks.CHISELED_BOOKSHELF);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)if(x*x+z*z<=25)h.setBlock(T.offset(x,-1,z),Blocks.BOOKSHELF);var t=(EnchantingTableBlockEntity)h.getBlockEntity(T);var enchant=h.getLevel().registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolder(r.enchantment()).orElseThrow();var other=h.getLevel().registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolder(id("minecraft:unbreaking")).orElseThrow();var target=new ItemStack(item);target.enchant(enchant,r.level());target.enchant(other,1);AltarStateService.target(t,target);var shelf=(ChiseledBookShelfBlockEntity)h.getBlockEntity(S);shelf.setItem(0,new ItemStack(Items.BOOK));var costs=r.extraction().orElseThrow().ingredients().stream().map(c->c.ingredient().getItems()[0].copyWithCount(1)).toList();var ps=UnitPedestals.set(h,T,costs);h.assertTrue(RitualController.startSelected(h.getLevel(),t.getBlockPos(),UUID.randomUUID(),r.id(),RitualType.EXTRACTION).started(),"Authored extraction did not match");h.runAtTickTime(250,()->{var out=EnchantmentHelper.getEnchantmentsForCrafting(AltarStateService.get(t).target());h.assertTrue(out.getLevel(enchant)==0&&out.getLevel(other)==1&&!AltarStateService.get(t).running(),"Wrong enchantment removed or active state leaked");h.assertTrue(ps.stream().allMatch(p->p.item().isEmpty()),"Authored reagents not consumed");var book=shelf.getItem(0);h.assertTrue(book.isEmpty()||(book.is(Items.ENCHANTED_BOOK)&&EnchantmentHelper.getEnchantmentsForCrafting(book).getLevel(enchant)==r.level()),"Invalid extraction output; default 20% failure is allowed");h.succeed();});}
}
